#pragma once
#include <winevt.h>
struct UsageEvidence {std::unordered_map<std::wstring,std::wstring> latest;std::wstring status;};
std::wstring decodeXml(std::wstring s){for(auto pair:std::vector<std::pair<std::wstring,std::wstring>>{{L"&quot;",L"\""},{L"&apos;",L"'"},{L"&lt;",L"<"},{L"&gt;",L">"},{L"&amp;",L"&"}}){size_t pos=0;while((pos=s.find(pair.first,pos))!=std::wstring::npos){s.replace(pos,pair.first.size(),pair.second);pos+=pair.second.size();}}return s;}
UsageEvidence recentUsage(const std::wstring& root,const std::function<bool()>& cancelled){UsageEvidence result;EVT_HANDLE query=EvtQuery(nullptr,L"Security",L"*[System[(EventID=4688) and TimeCreated[timediff(@SystemTime) <= 2592000000]]]",EvtQueryChannelPath|EvtQueryReverseDirection);if(!query){result.status=L"历史启动记录不可读取（权限或日志不可用），最近使用时间未知。";return result;}unsigned count=0;bool stopped=false;while(count<10000&&!cancelled()){EVT_HANDLE events[32];DWORD returned=0;if(!EvtNext(query,32,events,1000,0,&returned)){DWORD err=GetLastError();if(err!=ERROR_NO_MORE_ITEMS)stopped=true;break;}for(DWORD i=0;i<returned;i++){count++;DWORD used=0,props=0;EvtRender(nullptr,events[i],EvtRenderEventXml,0,nullptr,&used,&props);std::vector<wchar_t> buffer(used/sizeof(wchar_t)+1);if(used&&EvtRender(nullptr,events[i],EvtRenderEventXml,used,buffer.data(),&used,&props)){std::wstring xml=buffer.data();auto marker=xml.find(L"Name='NewProcessName'");if(marker==std::wstring::npos)marker=xml.find(L"Name=\"NewProcessName\"");if(marker!=std::wstring::npos){auto begin=xml.find(L'>',marker),end=xml.find(L'<',begin);if(begin!=std::wstring::npos&&end!=std::wstring::npos){auto path=decodeXml(xml.substr(begin+1,end-begin-1));if(inside(path,root)){auto t=xml.find(L"SystemTime=");if(t!=std::wstring::npos){t+=11;wchar_t quote=xml[t];auto last=xml.find(quote,t+1);if(last!=std::wstring::npos)result.latest.emplace(lower(path),xml.substr(t+1,last-t-1)+L"（UTC，启动审计）");}}}}}EvtClose(events[i]);}}EvtClose(query);result.status=L"查询范围：最近 30 天、最多 10000 条可读取的 4688 启动记录；无记录不代表从未使用。";if(stopped)result.status+=L" 部分日志读取失败。";return result;}
std::wstring localStartTime(const FILETIME& time){FILETIME local;SYSTEMTIME st;if(!FileTimeToLocalFileTime(&time,&local)||!FileTimeToSystemTime(&local,&st))return L"未知";wchar_t text[64];swprintf(text,64,L"%04u-%02u-%02u %02u:%02u:%02u",st.wYear,st.wMonth,st.wDay,st.wHour,st.wMinute,st.wSecond);return text;}
std::unordered_map<std::wstring,std::wstring> runningEvidence(const std::wstring& root){std::unordered_map<std::wstring,std::wstring> result;HANDLE snapshot=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if(snapshot==INVALID_HANDLE_VALUE)return result;PROCESSENTRY32W pe{};pe.dwSize=sizeof(pe);if(Process32FirstW(snapshot,&pe))do{HANDLE p=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,pe.th32ProcessID);if(!p)continue;wchar_t name[32768];DWORD n=32768;if(QueryFullProcessImageNameW(p,0,name,&n)&&inside(name,root)){FILETIME created,exit,kernel,user;result[lower(name)]=GetProcessTimes(p,&created,&exit,&kernel,&user)?L"正在运行；本次启动："+localStartTime(created):L"正在运行；启动时间不可读取";}CloseHandle(p);}while(Process32NextW(snapshot,&pe));CloseHandle(snapshot);return result;}
std::wstring productName(const fs::path& path){DWORD ignored=0,size=GetFileVersionInfoSizeW(path.c_str(),&ignored);if(!size||size>4*1024*1024)return path.filename().wstring();std::vector<BYTE> info(size);if(!GetFileVersionInfoW(path.c_str(),0,size,info.data()))return path.filename().wstring();struct Translation{WORD language,codepage;};Translation* translation=nullptr;UINT length=0;if(VerQueryValueW(info.data(),L"\\VarFileInfo\\Translation",(void**)&translation,&length)&&length>=sizeof(Translation)){wchar_t key[128];swprintf(key,128,L"\\StringFileInfo\\%04x%04x\\ProductName",translation[0].language,translation[0].codepage);wchar_t* value=nullptr;UINT chars=0;if(VerQueryValueW(info.data(),key,(void**)&value,&chars)&&chars>1)return value;}return path.filename().wstring();}
std::wstring inspectDirectory(const fs::path& root,const std::function<bool()>& cancelled){std::vector<fs::path> paths;std::vector<fs::path> directories{root};size_t checked=0,skipped=0;while(!directories.empty()&&checked<100000&&paths.size()<500&&!cancelled()){auto dir=directories.back();directories.pop_back();std::error_code ec;fs::directory_iterator it(dir,ec),end;if(ec){skipped++;continue;}while(it!=end&&!cancelled()){checked++;auto p=it->path();DWORD attrs=GetFileAttributesW(p.c_str());if(attrs==INVALID_FILE_ATTRIBUTES||attrs&FILE_ATTRIBUTE_REPARSE_POINT)skipped++;else if(attrs&FILE_ATTRIBUTE_DIRECTORY)directories.push_back(p);else if(lower(p.extension().wstring())==L".exe")paths.push_back(p);it.increment(ec);if(ec){skipped++;break;}if(checked>=100000||paths.size()>=500)break;}}
 if(cancelled())return L"";auto history=recentUsage(root.wstring(),cancelled);auto running=runningEvidence(root.wstring());std::wstring text=L"目录中的程序 / 组件候选："+std::to_wstring(paths.size())+L" 个 exe（不等于独立应用数量）\r\n"+history.status+L"\r\n跳过或不可读取："+std::to_wstring(skipped)+L" 处。";if(!directories.empty()||checked>=100000||paths.size()>=500)text+=L"已达到扫描上限，结果不完整。";text+=L"\r\n\r\n";for(auto&p:paths){if(cancelled())break;auto key=lower(p.wstring());text+=productName(p)+L"\r\n"+p.wstring()+L"\r\n";auto live=running.find(key);text+=live==running.end()?L"当前未观察到可读取的运行进程\r\n":live->second+L"\r\n";auto last=history.latest.find(key);text+=L"最近可查启动："+(last==history.latest.end()?L"未知（无可读取匹配记录）":last->second)+L"\r\n\r\n";}return text;}
